    children: [

      // ══════════════════════════════════════════════════════════════
      // PORTADA
      // ══════════════════════════════════════════════════════════════
      new Paragraph({ spacing: { before: 600, after: 200 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "PLAN MAESTRO DE COLABORACIÓN BINACIONAL", bold: true, size: 44, font: "Arial", color: BLUE_DARK })] }),
