          new TableRow({ children: [labelCell("Régimen Fiscal", 3200), dCell("Personas Morales con Fines no Lucrativos", 6160, ACCENT)] }),
          new TableRow({ children: [labelCell("Estatus Fiscal", 3200), dCell("ACTIVO (Validado al 06/ene/2026)", 6160)] }),
          new TableRow({ children: [labelCell("Trayectoria Institucional", 3200), dCell("Más de 25 años de operaciones (desde 30 de junio de 1999)", 6160, ACCENT)] }),
