      pageBreak(),

      // ══════════════════════════════════════════════════════════════
      // SECCIÓN 3 — DATOS DEL PROYECTO
      // ══════════════════════════════════════════════════════════════
      h1("SECCIÓN 3 — Datos del Proyecto"),
      spacer(),
      new Table({
