const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign, PageBreak, LevelFormat, TabStopType
} = require('docx');
const fs = require('fs');

// ─── PALETTE ────────────────────────────────────────────────────────────────
const NAVY      = "1B3A6B";
const BLUE      = "2563A8";
const BLUE_LT   = "D6E4F7";
const TEAL      = "0F6E56";
const TEAL_LT   = "E1F5EE";
const AMBER     = "854F0B";
const AMBER_LT  = "FAEEDA";
const CORAL     = "993C1D";
const CORAL_LT  = "FAECE7";
const GRAY      = "444444";
const GRAY_LT   = "F4F4F2";
const WHITE     = "FFFFFF";

// ─── BORDERS ────────────────────────────────────────────────────────────────
const cb  = { style: BorderStyle.SINGLE, size: 1, color: "BBCCE0" };
const cbs = { top: cb, bottom: cb, left: cb, right: cb };
const nb  = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const nbs = { top: nb, bottom: nb, left: nb, right: nb };

// ─── HELPERS ────────────────────────────────────────────────────────────────
const cm = (t, s, w) => new TableCell({
  borders: cbs, width: { size: w, type: WidthType.DXA },
  shading: { fill: s, type: ShadingType.CLEAR },
  margins: { top: 80, bottom: 80, left: 140, right: 140 },
  verticalAlign: VerticalAlign.TOP,
  children: [new Paragraph({ children: [new TextRun({ text: t, size: 18, font: "Arial", color: GRAY })] })]
});
const cmb = (t, s, w) => new TableCell({
  borders: cbs, width: { size: w, type: WidthType.DXA },
  shading: { fill: s, type: ShadingType.CLEAR },
  margins: { top: 80, bottom: 80, left: 140, right: 140 },
  verticalAlign: VerticalAlign.CENTER,
  children: [new Paragraph({ children: [new TextRun({ text: t, bold: true, size: 18, font: "Arial", color: GRAY })] })]
});
const hc = (t, fill, w) => new TableCell({
  borders: cbs, width: { size: w, type: WidthType.DXA },
  shading: { fill, type: ShadingType.CLEAR },
  margins: { top: 100, bottom: 100, left: 140, right: 140 },
  verticalAlign: VerticalAlign.CENTER,
  children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: t, bold: true, size: 18, font: "Arial", color: WHITE })] })]
});

function spacer(n = 80) {
  return new Paragraph({ spacing: { before: n, after: n }, children: [new TextRun("")] });
}
function pb() { return new Paragraph({ children: [new PageBreak()] }); }

function h1(text, color = NAVY) {
  return new Paragraph({
    spacing: { before: 400, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: BLUE, space: 4 } },
    children: [new TextRun({ text, bold: true, size: 32, color, font: "Arial" })]
  });
}
function h2(text, color = BLUE) {
  return new Paragraph({
    spacing: { before: 280, after: 80 },
    children: [new TextRun({ text, bold: true, size: 26, color, font: "Arial" })]
  });
}
function h3(text, color = TEAL) {
  return new Paragraph({
    spacing: { before: 200, after: 60 },
    children: [new TextRun({ text, bold: true, size: 22, color, font: "Arial" })]
  });
}
function body(text, { bold = false, italic = false, color = GRAY, before = 60, after = 60 } = {}) {
  return new Paragraph({
    spacing: { before, after },
    children: [new TextRun({ text, bold, italic, color, size: 20, font: "Arial" })]
  });
}
function bullet(text, color = GRAY) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text, size: 20, font: "Arial", color })]
  });
}
function subbullet(text) {
  return new Paragraph({
    numbering: { reference: "subbullets", level: 0 },
    spacing: { before: 30, after: 30 },
    children: [new TextRun({ text, size: 18, font: "Arial", color: GRAY })]
  });
}

// Folder header banner
function folderBanner(num, name, desc, fill) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      borders: nbs,
      width: { size: 9360, type: WidthType.DXA },
      shading: { fill, type: ShadingType.CLEAR },
      margins: { top: 140, bottom: 140, left: 200, right: 200 },
      children: [
        new Paragraph({ children: [new TextRun({ text: `📂 ${num} — ${name}`, bold: true, size: 28, font: "Arial", color: WHITE })] }),
        new Paragraph({ spacing: { before: 40 }, children: [new TextRun({ text: desc, size: 18, font: "Arial", color: "DDEEFF" })] }),
      ]
    })]})],
  });
}

// File entry row in a table
function fileRow(icon, filename, type, when, owner, desc, fillA, fillB) {
  return new TableRow({ children: [
    new TableCell({ borders: cbs, width: { size: 400, type: WidthType.DXA }, shading: { fill: fillA, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 100, right: 100 }, verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: icon, size: 20, font: "Arial", color: GRAY })] })] }),
    new TableCell({ borders: cbs, width: { size: 2600, type: WidthType.DXA }, shading: { fill: fillA, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP,
      children: [new Paragraph({ children: [new TextRun({ text: filename, bold: true, size: 18, font: "Arial", color: NAVY })] })] }),
    new TableCell({ borders: cbs, width: { size: 900, type: WidthType.DXA }, shading: { fill: fillA, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 100, right: 100 }, verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: type, size: 16, font: "Arial", color: GRAY })] })] }),
    new TableCell({ borders: cbs, width: { size: 1100, type: WidthType.DXA }, shading: { fill: fillB, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 100, right: 100 }, verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: when, size: 16, font: "Arial", color: GRAY })] })] }),
    new TableCell({ borders: cbs, width: { size: 1100, type: WidthType.DXA }, shading: { fill: fillB, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 100, right: 100 }, verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: owner, size: 16, font: "Arial", color: GRAY })] })] }),
    new TableCell({ borders: cbs, width: { size: 3260, type: WidthType.DXA }, shading: { fill: fillA, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP,
      children: [new Paragraph({ children: [new TextRun({ text: desc, size: 17, font: "Arial", color: GRAY })] })] }),
  ]});
}

function fileTableHeader() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [400, 2600, 900, 1100, 1100, 3260],
    rows: [
      new TableRow({ children: [
        hc("", NAVY, 400),
        hc("Nombre del archivo", NAVY, 2600),
        hc("Formato", NAVY, 900),
        hc("Cuándo se crea", NAVY, 1100),
        hc("Responsable", NAVY, 1100),
        hc("Contenido esperado", NAVY, 3260),
      ]}),
    ]
  });
}

function fileTable(rows) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [400, 2600, 900, 1100, 1100, 3260],
    rows
  });
}

// ─── CONTENT ROWS ────────────────────────────────────────────────────────────
// Alternating fills: A=light, B=white
const A = GRAY_LT; const B = WHITE;

// ════════════════════════════════════════════════════════════════════════════
const doc = new Document({
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
      { reference: "subbullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "◦", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 1080, hanging: 360 } } } }] },
      { reference: "numbered", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 20, color: GRAY } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 32, bold: true, font: "Arial", color: NAVY }, paragraph: { spacing: { before: 400, after: 120 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial", color: BLUE }, paragraph: { spacing: { before: 280, after: 80 }, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 22, bold: true, font: "Arial", color: TEAL }, paragraph: { spacing: { before: 200, after: 60 }, outlineLevel: 2 } },
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 15840, height: 12240 }, margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 } }
    },
    headers: {
      default: new Header({ children: [new Paragraph({
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: NAVY, space: 4 } },
        tabStops: [{ type: TabStopType.RIGHT, position: 13680 }],
        children: [
          new TextRun({ text: "ESTRUCTURA DE PROYECTO  |  AZ-CHIH-ATP-2026  |  INADET & ASU", bold: true, size: 16, font: "Arial", color: NAVY }),
          new TextRun({ text: "\tGuía de Gestión Documental — v1.0  |  Marzo 2026", size: 16, font: "Arial", color: "888888" })
        ]
      })] })
    },
    footers: {
      default: new Footer({ children: [new Paragraph({
        border: { top: { style: BorderStyle.SINGLE, size: 4, color: BLUE_LT, space: 4 } },
        spacing: { before: 80 },
        children: [new TextRun({ text: "Documento de uso interno — INADET  |  Versión 1.0  |  Confidencial donde se indica", size: 15, font: "Arial", color: "AAAAAA" })]
      })] })
    },

    children: [

      // ══════ PORTADA ══════
      new Paragraph({ spacing: { before: 800, after: 200 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "ESTRUCTURA DE GESTIÓN DOCUMENTAL", bold: true, size: 48, font: "Arial", color: NAVY })] }),
      new Paragraph({ spacing: { before: 0, after: 100 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Proyecto AZ-CHIH-ATP-2026", bold: true, size: 30, font: "Arial", color: BLUE })] }),
      new Paragraph({ spacing: { before: 0, after: 600 }, alignment: AlignmentType.CENTER,
        border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: BLUE, space: 8 } },
        children: [new TextRun({ text: "Guía completa de carpetas, archivos, contenidos, responsables y fechas clave", italic: true, size: 22, font: "Arial", color: "666666" })] }),

      new Table({
        width: { size: 8000, type: WidthType.DXA },
        columnWidths: [2600, 5400],
        rows: [
          new TableRow({ children: [cmb("Proyecto", BLUE_LT, 2600), cm("ASU Semiconductor Strategy Co-Design and Immersion ATP Program", BLUE_LT, 5400)] }),
          new TableRow({ children: [cmb("Código", WHITE, 2600), cm("AZ-CHIH-ATP-2026", WHITE, 5400)] }),
          new TableRow({ children: [cmb("Período", BLUE_LT, 2600), cm("Mayo 2026 — Diciembre 2026 (seguimiento hasta junio 2027)", BLUE_LT, 5400)] }),
          new TableRow({ children: [cmb("Entidad ejecutora", WHITE, 2600), cm("INADET — Instituto de Apoyo al Desarrollo Tecnológico", WHITE, 5400)] }),
          new TableRow({ children: [cmb("Socio académico", BLUE_LT, 2600), cm("Arizona State University — Ira A. Fulton Schools of Engineering", BLUE_LT, 5400)] }),
          new TableRow({ children: [cmb("Presupuesto total", WHITE, 2600), cm("$158,750 USD (fondos SIDE Chihuahua)", WHITE, 5400)] }),
          new TableRow({ children: [cmb("Versión del documento", BLUE_LT, 2600), cm("1.0 — Marzo 2026", BLUE_LT, 5400)] }),
        ]
