const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign, PageNumber, LevelFormat, PageBreak,
  TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Color palette ──────────────────────────────────────────────
const BLUE_DARK   = "1B3A6B";
const BLUE_MED    = "2E5FA3";
const BLUE_LIGHT  = "D5E3F5";
const BLUE_SOFT   = "EBF2FB";
const GRAY_DARK   = "444444";
const GRAY_MED    = "666666";
const GRAY_LIGHT  = "F2F2F2";
const WHITE       = "FFFFFF";
const ACCENT      = "C0392B"; // rojo tenue para badge "Urgente"

// ── Border helpers ─────────────────────────────────────────────
const border = (color = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 4, color });
const borders = (color = "CCCCCC") => ({
  top: border(color), bottom: border(color),
  left: border(color), right: border(color)
});
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

// ── Spacing helpers ────────────────────────────────────────────
const sp = (before = 0, after = 0) => ({ spacing: { before, after } });

// ── Text helpers ───────────────────────────────────────────────
const run = (text, opts = {}) => new TextRun({ text, font: "Arial", ...opts });
const bold = (text, size = 24, color = GRAY_DARK) =>
  run(text, { bold: true, size, color });

// ── Paragraph helpers ──────────────────────────────────────────
const para = (children, opts = {}) =>
  new Paragraph({ children: Array.isArray(children) ? children : [children], ...opts });

const heading1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [run(text, { bold: true, size: 32, color: WHITE })],
  shading: { fill: BLUE_DARK, type: ShadingType.CLEAR },
  spacing: { before: 320, after: 160 },
  indent: { left: 200, right: 200 },
});

const heading2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [run(text, { bold: true, size: 26, color: BLUE_DARK })],
  spacing: { before: 280, after: 100 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BLUE_MED, space: 4 } },
});

const heading3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  children: [run(text, { bold: true, size: 24, color: BLUE_MED })],
  spacing: { before: 200, after: 80 },
});

const body = (text, opts = {}) => new Paragraph({
  children: [run(text, { size: 22, color: GRAY_DARK })],
  spacing: { before: 80, after: 80 },
  ...opts,
});

const bullet = (text, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  children: [run(text, { size: 22, color: GRAY_DARK })],
  spacing: { before: 60, after: 60 },
});

const space = (n = 120) => new Paragraph({ children: [run("")], spacing: { before: 0, after: n } });

// ── Cell helpers ───────────────────────────────────────────────
const headerCell = (text, width, colSpan = 1) => new TableCell({
  width: { size: width, type: WidthType.DXA },
  columnSpan: colSpan,
  shading: { fill: BLUE_DARK, type: ShadingType.CLEAR },
  borders: borders(BLUE_DARK),
  margins: { top: 100, bottom: 100, left: 120, right: 120 },
  verticalAlign: VerticalAlign.CENTER,
  children: [new Paragraph({
    alignment: AlignmentType.LEFT,
    children: [run(text, { bold: true, size: 20, color: WHITE })],
  })],
});

const subHeaderCell = (text, width, colSpan = 1) => new TableCell({
  width: { size: width, type: WidthType.DXA },
  columnSpan: colSpan,
  shading: { fill: BLUE_LIGHT, type: ShadingType.CLEAR },
  borders: borders("A8C5E8"),
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  verticalAlign: VerticalAlign.CENTER,
  children: [new Paragraph({
    children: [run(text, { bold: true, size: 20, color: BLUE_DARK })],
  })],
});

const dataCell = (text, width, shade = WHITE, textColor = GRAY_DARK, bold_ = false) => new TableCell({
  width: { size: width, type: WidthType.DXA },
  shading: { fill: shade, type: ShadingType.CLEAR },
  borders: borders("CCCCCC"),
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  verticalAlign: VerticalAlign.CENTER,
  children: [new Paragraph({
    children: [run(text, { size: 20, color: textColor, bold: bold_ })],
  })],
});

const richCell = (children_arr, width, shade = WHITE) => new TableCell({
  width: { size: width, type: WidthType.DXA },
  shading: { fill: shade, type: ShadingType.CLEAR },
