const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageNumber, NumberFormat, LevelFormat, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ─── COLOR PALETTE ────────────────────────────────────────────────────────────
const C = {
  azul:    "1F4E79",
  azulMed: "2E75B6",
  azulCla: "D6E4F0",
  gris:    "404040",
  grisCla: "F2F2F2",
  rojo:    "C00000",
  verde:   "375623",
  amarillo:"FFC000",
  blanco:  "FFFFFF",
};

// ─── HELPERS ──────────────────────────────────────────────────────────────────
const bold  = (t, sz=22, color=C.gris)  => new TextRun({ text:t, bold:true,  size:sz, color, font:"Arial" });
const norm  = (t, sz=20, color=C.gris)  => new TextRun({ text:t, bold:false, size:sz, color, font:"Arial" });
const ital  = (t, sz=20, color=C.gris)  => new TextRun({ text:t, bold:false, italics:true, size:sz, color, font:"Arial" });

const para  = (children, opts={}) => new Paragraph({ children, spacing:{after:120}, ...opts });
const hdr1  = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [new TextRun({ text, bold:true, size:28, color:C.azul, font:"Arial" })],
  spacing: { before:360, after:180 },
  border: { bottom: { style:BorderStyle.SINGLE, size:6, color:C.azulMed, space:1 } }
});
const hdr2  = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [new TextRun({ text, bold:true, size:24, color:C.azulMed, font:"Arial" })],
  spacing: { before:240, after:120 }
});
const hdr3  = (text) => new Paragraph({
  children: [new TextRun({ text, bold:true, size:22, color:C.azul, font:"Arial" })],
  spacing: { before:180, after:80 }
});

const pageBreak = () => new Paragraph({ children:[new PageBreak()] });

const cellH = (text, w, color=C.azul) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill:color, type:ShadingType.CLEAR },
  margins:{ top:80, bottom:80, left:120, right:120 },
  borders: {
    top:   { style:BorderStyle.SINGLE, size:2, color:C.blanco },
    bottom:{ style:BorderStyle.SINGLE, size:2, color:C.blanco },
    left:  { style:BorderStyle.SINGLE, size:2, color:C.blanco },
    right: { style:BorderStyle.SINGLE, size:2, color:C.blanco },
  },
  children:[ new Paragraph({ children:[new TextRun({ text, bold:true, size:18, color:C.blanco, font:"Arial" })], alignment:AlignmentType.CENTER }) ]
});

const cellB = (text, w, shade=C.blanco, textColor=C.gris, sz=18) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill:shade, type:ShadingType.CLEAR },
  margins:{ top:80, bottom:80, left:120, right:120 },
  borders: {
    top:   { style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
    bottom:{ style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
    left:  { style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
    right: { style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
  },
  children:[ new Paragraph({ children:[new TextRun({ text, size:sz, color:textColor, font:"Arial" })], spacing:{after:40} }) ]
});

const cellBB = (runs, w, shade=C.blanco) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill:shade, type:ShadingType.CLEAR },
  margins:{ top:80, bottom:80, left:120, right:120 },
  borders: {
    top:   { style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
    bottom:{ style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
    left:  { style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
    right: { style:BorderStyle.SINGLE, size:1, color:"CCCCCC" },
  },
  children:[ new Paragraph({ children:runs, spacing:{after:40} }) ]
});

// ══════════════════════════════════════════════════════════════════════════════
// DOCUMENTO 1 — PROTOCOLO SEGUNDO REVISOR
// ══════════════════════════════════════════════════════════════════════════════
function buildDoc1() {
  const W = 9360;
  const children = [

    // PORTADA
    new Paragraph({
      children:[new TextRun({ text:"PROTOCOLO PARA SEGUNDO REVISOR", bold:true, size:36, color:C.azul, font:"Arial" })],
      alignment:AlignmentType.CENTER, spacing:{ before:720, after:240 }
    }),
    new Paragraph({
      children:[new TextRun({ text:"Revisión Sistemática: Swarm Intelligence para\nPath Planning Multi-UAV en Agricultura de Precisión", size:26, color:C.azulMed, font:"Arial", italics:true })],
      alignment:AlignmentType.CENTER, spacing:{ after:160 }
    }),
    new Paragraph({
      children:[new TextRun({ text:"Versión 1.0  |  Marzo 2026", size:20, color:C.gris, font:"Arial" })],
      alignment:AlignmentType.CENTER, spacing:{ after:480 }
    }),
    new Paragraph({
      children:[new TextRun({ text:"Autor principal: Andres Hidalgo Morales  |  Instituto Tecnológico de Chihuahua II, TecNM", size:20, color:C.gris, font:"Arial" })],
      alignment:AlignmentType.CENTER, spacing:{ after:80 }
    }),
    new Paragraph({
      children:[new TextRun({ text:"Segundo revisor (tu director de tesis): ______________________________", size:20, color:C.gris, font:"Arial" })],
      alignment:AlignmentType.CENTER, spacing:{ after:720 }
    }),

    // Nota de alerta
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[W],
      rows:[new TableRow({ children:[
        new TableCell({
          width:{ size:W, type:WidthType.DXA },
          shading:{ fill:"FFF2CC", type:ShadingType.CLEAR },
          margins:{ top:120, bottom:120, left:180, right:180 },
          borders:{ top:{style:BorderStyle.SINGLE,size:4,color:C.amarillo}, bottom:{style:BorderStyle.SINGLE,size:4,color:C.amarillo}, left:{style:BorderStyle.SINGLE,size:4,color:C.amarillo}, right:{style:BorderStyle.SINGLE,size:4,color:C.amarillo} },
          children:[
            new Paragraph({ children:[bold("¿Por qué es necesaria tu participación?",22,C.gris)], spacing:{after:80} }),
            new Paragraph({ children:[norm("Las guías PRISMA 2020 y los editores de Computers and Electronics in Agriculture (IF 8.9) requieren que la selección de artículos sea realizada por al menos dos revisores independientes. Tu participación convierte este paper de una revisión narrativa a una systematic review publicable en Q1. El proceso toma aproximadamente 3–4 horas de tu tiempo.",20)], spacing:{after:40} }),
          ]
        })
      ]})]
    }),
    new Paragraph({ children:[], spacing:{after:240} }),

    pageBreak(),

    // SECCIÓN 1
    hdr1("1. Contexto y objetivo de tu revisión"),
    para([norm("Este paper es una revisión sistemática que analiza 33 estudios publicados entre 2021 y 2025 sobre el uso de algoritmos de inteligencia de enjambre (Swarm Intelligence) para la planificación de rutas de múltiples drones (multi-UAV) en agricultura de precisión.")]),
    para([norm("Tu rol específico es actuar como segundo revisor independiente en la etapa de selección de artículos de texto completo (full-text screening). Esto significa que revisarás los mismos 51 artículos que el autor principal revisó, sin conocer sus decisiones previas, y determinarás cuáles cumplen los criterios de inclusión.")]),
    para([bold("Tu decisión es completamente independiente. ",20), norm("No consultes las decisiones del autor principal hasta que hayas completado tu propio formulario de selección.")]),

    hdr2("1.1 Tiempo estimado"),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[3000, 2500, 3860],
      rows:[
        new TableRow({ children:[ cellH("Actividad",3000), cellH("Tiempo estimado",2500), cellH("Descripción",3860) ] }),
        new TableRow({ children:[ cellB("Leer este protocolo",3000,C.grisCla), cellB("20 min",2500,C.grisCla), cellB("Familiarizarte con criterios",3860,C.grisCla) ] }),
        new TableRow({ children:[ cellB("Full-text screening (51 art.)",3000), cellB("2.5–3.5 horas",2500), cellB("~3–4 min por artículo",3860) ] }),
        new TableRow({ children:[ cellB("Cálculo de acuerdo (kappa)",3000,C.grisCla), cellB("20 min",2500,C.grisCla), cellB("Usa la hoja de Excel adjunta",3860,C.grisCla) ] }),
        new TableRow({ children:[ cellB("TOTAL",3000,C.azulCla), cellBB([bold("~3–4 horas",20,C.azul)],2500,C.azulCla), cellB("Una sola sesión o dos sesiones",3860,C.azulCla) ] }),
      ]
    }),

    new Paragraph({ children:[], spacing:{after:240} }),
    pageBreak(),

    // SECCIÓN 2
    hdr1("2. Criterios de inclusión y exclusión"),
    para([norm("Lee estos criterios cuidadosamente antes de comenzar. Son los mismos que usó el autor principal y definen qué artículos entran al corpus final de la revisión sistemática.")]),

    hdr2("2.1 Criterios de INCLUSIÓN — el artículo debe cumplir TODOS"),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[500, 2200, 4660, 2000],
      rows:[
        new TableRow({ children:[ cellH("#",500), cellH("Criterio",2200), cellH("Descripción detallada",4660), cellH("Verificar en...",2000) ] }),
        new TableRow({ children:[ cellB("I1",500,C.grisCla), cellB("Período de publicación",2200,C.grisCla), cellB("Publicado entre enero 2021 y diciembre 2025",4660,C.grisCla), cellB("Año en portada / metadata",2000,C.grisCla) ] }),
        new TableRow({ children:[ cellB("I2",500), cellB("Tipo de publicación",2200), cellB("Artículo de revista peer-reviewed O artículo de conferencia peer-reviewed. Excluye: preprints, tesis, capítulos de libro sin revisión.",4660), cellB("Tipo de publicación en portal",2000) ] }),
        new TableRow({ children:[ cellB("I3",500,C.grisCla), cellB("Idioma",2200,C.grisCla), cellB("Texto completo disponible en inglés",4660,C.grisCla), cellB("Idioma del PDF",2000,C.grisCla) ] }),
        new TableRow({ children:[ cellB("I4",500), cellB("Algoritmo SI",2200), cellB("Usa al menos un algoritmo de Swarm Intelligence para path planning: PSO, ACO, ABC, SSA, GWO, DBO, NOA, DOA, o variantes híbridas que incluyan SI.",4660), cellB("Abstract / Methods",2000) ] }),
        new TableRow({ children:[ cellB("I5",500,C.grisCla), cellB("Aplicación agrícola",2200,C.grisCla), cellB("Menciona o implica aplicación en agricultura: monitoreo de cultivos, fumigación, mapeo de campo, estimación de rendimiento, detección de plagas.",4660,C.grisCla), cellB("Abstract / Introduction",2000,C.grisCla) ] }),
        new TableRow({ children:[ cellB("I6",500), cellB("Texto completo",2200), cellB("El PDF del texto completo está disponible y accesible",4660), cellB("Descarga del PDF",2000) ] }),
      ]
    }),
    new Paragraph({ children:[], spacing:{after:200} }),

    hdr2("2.2 Criterios de EXCLUSIÓN — excluye si cumple CUALQUIERA"),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[500, 2200, 6660],
      rows:[
        new TableRow({ children:[ cellH("#",500), cellH("Criterio",2200), cellH("Descripción",6660) ] }),
        new TableRow({ children:[ cellB("E1",500,C.grisCla), cellB("Duplicado",2200,C.grisCla), cellB("Ya está incluido en otra forma (versión extendida de conferencia cuando existe el journal paper, etc.)",6660,C.grisCla) ] }),
        new TableRow({ children:[ cellB("E2",500), cellB("Solo abstract",2200), cellB("No hay texto completo disponible",6660) ] }),
        new TableRow({ children:[ cellB("E3",500,C.grisCla), cellB("UAV único",2200,C.grisCla), cellB("El estudio se centra exclusivamente en un solo UAV, sin coordinación de enjambre o flota",6660,C.grisCla) ] }),
        new TableRow({ children:[ cellB("E4",500), cellB("No-SI",2200), cellB("El método de optimización no es SI: solo usa algoritmos genéticos puros, A*, Dijkstra, métodos clásicos de control, o RL sin componente SI",6660) ] }),
        new TableRow({ children:[ cellB("E5",500,C.grisCla), cellB("Sin agricultura",2200,C.grisCla), cellB("Aplicación exclusivamente en otros dominios: militar, búsqueda y rescate, inspección de infraestructura urbana, sin mención a agricultura",6660,C.grisCla) ] }),
      ]
    }),

    new Paragraph({ children:[], spacing:{after:200} }),
    hdr2("2.3 Casos dudosos — cómo proceder"),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[3000, 6360],
      rows:[
        new TableRow({ children:[ cellH("Situación",3000), cellH("Decisión recomendada",6360) ] }),
        new TableRow({ children:[ cellB("Aplica SI + método no-SI comparado",3000,C.grisCla), cellB("INCLUIR si el componente principal es SI. Excluir si SI es solo el baseline de comparación.",6360,C.grisCla) ] }),
        new TableRow({ children:[ cellB("Agricultura mencionada solo en motivación",3000), cellB("INCLUIR si hay parámetros agrícolas en la metodología (tamaño de campo, cobertura de cultivos, etc.)",6360) ] }),
        new TableRow({ children:[ cellB("Review paper incluido en el corpus",3000,C.grisCla), cellB("INCLUIR si el review se centra en SI para multi-UAV agrícola. Estos son válidos como estudios incluidos.",6360,C.grisCla) ] }),
        new TableRow({ children:[ cellB("Año de publicación = 2025 y datos incompletos",3000), cellB("INCLUIR si el texto completo está disponible con metodología completa",6360) ] }),
        new TableRow({ children:[ cellB("Duda genuina",3000,C.grisCla), cellB("Marca como 'Dudoso' en el formulario. No fuerces una decisión. El autor principal y tú resolverán las dudas por consenso.",6360,C.grisCla) ] }),
      ]
    }),

    new Paragraph({ children:[], spacing:{after:200} }),
    pageBreak(),

    // SECCIÓN 3
    hdr1("3. Instrucciones paso a paso"),
    hdr2("Paso 1 — Recibe la lista de 51 artículos"),
    para([norm("El autor principal te enviará: (a) una hoja de Excel con los 51 artículos y sus DOIs, y (b) acceso a los PDFs o links de descarga. No te enviará sus decisiones de inclusión/exclusión.")]),

    hdr2("Paso 2 — Para cada artículo, lee en este orden"),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[500, 2500, 6360],
      rows:[
        new TableRow({ children:[ cellH("Orden",500), cellH("Qué leer",2500), cellH("Para verificar qué criterio",6360) ] }),
        new TableRow({ children:[ cellB("1°",500,C.grisCla), cellB("Título y abstract",2500,C.grisCla), cellB("I1, I2, I3, I4, I5 — en 90% de los casos es suficiente para decidir",6360,C.grisCla) ] }),
        new TableRow({ children:[ cellB("2°",500), cellB("Introduction (primer y último párrafo)",2500), cellB("Confirmar aplicación agrícola si el abstract es ambiguo",6360) ] }),
        new TableRow({ children:[ cellB("3°",500,C.grisCla), cellB("Methods (nombre del algoritmo)",2500,C.grisCla), cellB("Confirmar que el algoritmo es SI si el abstract no lo especifica",6360,C.grisCla) ] }),
        new TableRow({ children:[ cellB("4°",500), cellB("Texto completo solo si aún hay duda",2500), cellB("Para casos marcados como 'Dudoso' después de pasos 1–3",6360) ] }),
      ]
    }),
    new Paragraph({ children:[], spacing:{after:160} }),

    hdr2("Paso 3 — Registra tu decisión en el formulario"),
    para([norm("Para cada artículo registra: Incluir / Excluir / Dudoso, el criterio de exclusión si aplica (E1–E5), y un comentario breve si marcas 'Dudoso'. El formulario está en las páginas siguientes de este documento y también en hoja de Excel separada.")]),

    hdr2("Paso 4 — Envía tu formulario"),
    para([norm("Cuando termines los 51 artículos, envía tu formulario al autor principal SIN ver sus decisiones. El autor calculará el Cohen's kappa. Si κ ≥ 0.61, el proceso es válido para publicación en CEA.")]),

    hdr2("Paso 5 — Resolución de discrepancias"),
    para([norm("El autor principal te presentará los casos donde sus decisiones difieren de las tuyas. Discutirán cada caso y llegarán a una decisión consensuada. Si no hay acuerdo, se consultará la opinión de un tercer revisor (o se aplica el criterio de inclusión como desempate).")]),

    pageBreak(),

    // SECCIÓN 4 — FORMULARIO
    hdr1("4. Formulario de selección — Full-text Screening"),
    para([bold("Instrucción: ",20), norm("Para cada artículo, marca tu decisión y el criterio de exclusión si aplica. Completa en lápiz/bolígrafo o en la versión digital Excel.")]),
    new Paragraph({ children:[], spacing:{after:160} }),

    // Tabla del formulario — 51 artículos (mostramos la estructura completa con 10 de ejemplo, el resto son filas idénticas)
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[400, 3200, 1100, 1200, 800, 2660],
      rows:[
        new TableRow({ children:[
          cellH("#",400), cellH("Título del artículo (primeras palabras)",3200),
          cellH("Decisión",1100), cellH("Criterio excl.",1200), cellH("Tiempo\n(min)",800), cellH("Comentario / Duda",2660)
        ]}),
        ...[...Array(51)].map((_,i) => {
          const shade = i%2===0 ? C.blanco : C.grisCla;
          return new TableRow({ children:[
            cellB(`${String(i+1).padStart(2,'0')}`, 400, shade),
