          cellBB([bold("TOTAL",18,C.azul)],400,C.azulCla),
          cellBB([bold("51 artículos",18,C.azul)],3200,C.azulCla),
          cellBB([bold("Incl: ___\nExcl: ___\nDud: ___",18,C.azul)],1100,C.azulCla),
          cellB("",1200,C.azulCla),
          cellBB([bold("Total:\n___min",18,C.azul)],800,C.azulCla),
          cellB("",2660,C.azulCla),
        ]})
      ]
    }),

    pageBreak(),

    // SECCIÓN 5 — CÁLCULO KAPPA
    hdr1("5. Cálculo del Cohen's kappa"),
    para([norm("Una vez que ambos revisores han completado sus formularios de forma independiente, el autor principal calculará el Cohen's kappa (κ) usando la siguiente fórmula:")]),
    new Paragraph({
      children:[new TextRun({ text:"κ = (Po − Pe) / (1 − Pe)", bold:true, size:22, font:"Courier New", color:C.azul })],
      alignment: AlignmentType.CENTER, spacing:{ before:160, after:160 }
    }),
    para([norm("donde Po = proporción de acuerdo observado, Pe = proporción de acuerdo esperado por azar.")]),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[2500, 3860, 3000],
