        new TableRow({ children:[ cellB("0.61 – 0.80",2500,"E2EFDA"), cellB("Acuerdo sustancial",3860,"E2EFDA"), cellB("Aceptable para publicación en CEA",3000,"E2EFDA") ] }),
        new TableRow({ children:[ cellB("0.81 – 1.00",2500,C.azulCla), cellB("Acuerdo casi perfecto",3860,C.azulCla), cellB("Excelente — reportar en Methods",3000,C.azulCla) ] }),
      ]
    }),
    new Paragraph({ children:[], spacing:{after:200} }),
    para([norm("El resultado del kappa se reportará en la Sección 3.1 del manuscrito con el texto: \"Study selection was performed by two independent reviewers. Inter-rater agreement was assessed using Cohen's kappa (κ = [valor]), indicating [nivel] agreement. Discrepancies were resolved through discussion and consensus.\"")]),

    pageBreak(),

    // FIRMA
    hdr1("6. Confirmación de participación"),
    new Table({
      width:{ size:W, type:WidthType.DXA }, columnWidths:[4680, 4680],
      rows:[
        new TableRow({ children:[
          new TableCell({
            width:{ size:4680, type:WidthType.DXA },
            shading:{ fill:C.grisCla, type:ShadingType.CLEAR },
            margins:{ top:200, bottom:200, left:180, right:180 },
            borders:{ top:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, bottom:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, left:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, right:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"} },
            children:[
