const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageBreak, LevelFormat
} = require('docx');
const fs = require('fs');

const C = {
  azul:    "1F4E79",
  azulMed: "2E75B6",
  azulCla: "D6E4F0",
  gris:    "404040",
  grisCla: "F5F5F5",
  rojo:    "C00000",
  rojoCla: "FCE4E4",
  verde:   "375623",
  verdeCla:"E2EFDA",
  amarillo:"806000",
  amarCla: "FFF2CC",
  naranja: "843C0C",
  narCla:  "FCE9D8",
  blanco:  "FFFFFF",
  negro:   "000000",
};

const t = (text, opts={}) => new TextRun({ text, font:"Arial", size:20, color:C.gris, ...opts });
const bold = (text, sz=20, color=C.gris) => new TextRun({ text, font:"Arial", size:sz, bold:true, color });
const mono = (text) => new TextRun({ text, font:"Courier New", size:18, color:C.azulMed });

const p = (children, opts={}) => new Paragraph({ children: Array.isArray(children) ? children : [children], spacing:{after:100}, ...opts });
const pb = () => new Paragraph({ children:[new PageBreak()] });

const hdr1 = (text, color=C.azul) => new Paragraph({
  children:[new TextRun({ text, bold:true, size:32, color, font:"Arial" })],
  spacing:{ before:400, after:200 },
  border:{ bottom:{ style:BorderStyle.SINGLE, size:8, color:C.azulMed, space:1 } }
});

const hdr2 = (text, color=C.azulMed) => new Paragraph({
  children:[new TextRun({ text, bold:true, size:24, color, font:"Arial" })],
  spacing:{ before:280, after:120 }
});

const hdr3 = (text, color=C.gris) => new Paragraph({
  children:[new TextRun({ text, bold:true, size:20, color, font:"Arial" })],
  spacing:{ before:180, after:80 }
});

// Badge cell
const badge = (text, fill, textColor=C.blanco, w=1400) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill, type:ShadingType.CLEAR },
  margins:{ top:60, bottom:60, left:120, right:120 },
  verticalAlign:"center",
  borders:{
    top:{style:BorderStyle.SINGLE,size:1,color:fill},
    bottom:{style:BorderStyle.SINGLE,size:1,color:fill},
    left:{style:BorderStyle.SINGLE,size:1,color:fill},
    right:{style:BorderStyle.SINGLE,size:1,color:fill},
  },
  children:[new Paragraph({ alignment:AlignmentType.CENTER, children:[new TextRun({ text, bold:true, size:16, color:textColor, font:"Arial" })] })]
});

const cell = (children, w, fill=C.blanco, border="CCCCCC") => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill, type:ShadingType.CLEAR },
  margins:{ top:80, bottom:80, left:140, right:140 },
  borders:{
    top:{style:BorderStyle.SINGLE,size:1,color:border},
    bottom:{style:BorderStyle.SINGLE,size:1,color:border},
    left:{style:BorderStyle.SINGLE,size:1,color:border},
    right:{style:BorderStyle.SINGLE,size:1,color:border},
  },
  children: Array.isArray(children) ? children : [new Paragraph({ children:[children], spacing:{after:40} })]
});

const hdrCell = (text, w, fill=C.azul) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill, type:ShadingType.CLEAR },
  margins:{ top:80, bottom:80, left:140, right:140 },
  borders:{
    top:{style:BorderStyle.SINGLE,size:1,color:C.blanco},
    bottom:{style:BorderStyle.SINGLE,size:1,color:C.blanco},
    left:{style:BorderStyle.SINGLE,size:1,color:C.blanco},
    right:{style:BorderStyle.SINGLE,size:1,color:C.blanco},
  },
  children:[new Paragraph({ alignment:AlignmentType.CENTER, children:[new TextRun({ text, bold:true, size:18, color:C.blanco, font:"Arial" })] })]
});

// Checkbox row  
const chkRow = (num, task, detail, phase, phaseColor, effort, docRef, shade) => {
  return new TableRow({ children:[
    // Checkbox
    cell([new Paragraph({ alignment:AlignmentType.CENTER, children:[t("☐", {size:22, bold:true})], spacing:{after:0} })], 420, shade),
    // Num
    cell([new Paragraph({ children:[bold(`${num}`, 18, C.azulMed)], spacing:{after:0} })], 380, shade),
    // Task
    cell([
      new Paragraph({ children:[bold(task, 18, C.gris)], spacing:{after:40} }),
      new Paragraph({ children:[t(detail, {size:16, color:"666666"})], spacing:{after:0} }),
    ], 4000, shade),
    // Phase badge
    new TableCell({
      width:{ size:1100, type:WidthType.DXA },
      shading:{ fill:phaseColor+"22", type:ShadingType.CLEAR },
      margins:{ top:80, bottom:80, left:80, right:80 },
      borders:{ top:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, bottom:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, left:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, right:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"} },
      children:[new Paragraph({ alignment:AlignmentType.CENTER, children:[new TextRun({ text:phase, bold:true, size:15, color:phaseColor, font:"Arial" })] })]
    }),
    // Effort
    cell([new Paragraph({ alignment:AlignmentType.CENTER, children:[t(effort,{size:16})], spacing:{after:0} })], 900, shade),
    // Doc ref
    new TableCell({
      width:{ size:1700, type:WidthType.DXA },
      shading:{ fill: docRef.startsWith("Doc") ? C.azulCla : shade, type:ShadingType.CLEAR },
      margins:{ top:80, bottom:80, left:100, right:100 },
      borders:{ top:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, bottom:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, left:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"}, right:{style:BorderStyle.SINGLE,size:1,color:"CCCCCC"} },
      children:[new Paragraph({ children:[t(docRef, {size:15, color: docRef.startsWith("Doc") ? C.azulMed : C.gris})], spacing:{after:0} })]
    }),
  ]});
};

// Section divider row
const secRow = (text, fill) => new TableRow({
  children:[new TableCell({
    columnSpan:6,
    width:{ size:8500, type:WidthType.DXA },
    shading:{ fill, type:ShadingType.CLEAR },
    margins:{ top:100, bottom:100, left:160, right:160 },
    borders:{ top:{style:BorderStyle.SINGLE,size:3,color:fill}, bottom:{style:BorderStyle.SINGLE,size:3,color:fill}, left:{style:BorderStyle.SINGLE,size:3,color:fill}, right:{style:BorderStyle.SINGLE,size:3,color:fill} },
    children:[new Paragraph({ children:[new TextRun({ text, bold:true, size:20, color:C.blanco, font:"Arial" })] })]
  })]
});

// ─── ITEMS ────────────────────────────────────────────────────────────────────
// [num, task, detail, phase, phaseColor, effort, docRef]
const W = 9360;

const items = [
  // BLOQUE 1 — CRÍTICO (sin esto = rechazo automático)
  ["SEC1", "── BLOQUE 1: ACCIONES CRÍTICAS — Sin estas, el editor rechaza sin revisar ──", C.rojo],

  ["01", "Incorporar segundo revisor (tu director)",
   "Entregarle el Protocolo (Doc 01). Él revisa los 51 artículos de forma independiente sin ver tus decisiones previas.",
   "BLOQUEADOR", C.rojo, "3–4 h (él)", "Doc 01 ✓"],

  ["02", "Calcular Cohen's kappa",
   "Una vez que tu director termine, comparar decisiones y calcular κ. Meta: κ ≥ 0.61. Reportar en Sección 3.1 del manuscrito.",
   "BLOQUEADOR", C.rojo, "30 min", "Doc 01 ✓"],

  ["03", "Resolver discrepancias entre revisores",
   "Los artículos donde difieran deben discutirse y llegar a consenso documentado. Registrar los casos y decisiones finales.",
   "BLOQUEADOR", C.rojo, "1–2 h", "Doc 01 ✓"],

  ["04", "Expandir manuscrito a 8,000–10,000 palabras",
   "Actualmente ~5,000 palabras. Integrar: Discussion expandida (Doc 04), Tabla de estudios (Doc 03), comparativa de reviews previos.",
   "BLOQUEADOR", C.rojo, "2–3 días", "Doc 04 ✓"],

  ["05", "Agregar Risk of Bias assessment (MMAT)",
   "Aplicar el Mixed Methods Appraisal Tool a los 33 estudios. Crear tabla con resultados. Es requisito PRISMA 2020 innegociable.",
   "BLOQUEADOR", C.rojo, "4–6 h", "Manual"],

  // BLOQUE 2 — MAYOR
  ["SEC2", "── BLOQUE 2: CAMBIOS MAYORES — El reviewer los pedirá en ronda 1 ──", C.naranja],

  ["06", "Completar lista de referencias del corpus",
   "Los 33 estudios revisados deben aparecer como referencias completas con DOI. Actualmente solo hay 26 citas de background.",
   "MAYOR", C.naranja, "2–3 h", "BibTeX"],

  ["07", "Crear tabla comparativa con reviews previos",
   "Tabla que muestre los 6 reviews previos vs. este paper columna a columna: período, n estudios, gap analysis, benchmark propuesto.",
   "MAYOR", C.naranja, "2 h", "Nuevo"],

  ["08", "Enviar Formulario de Gaps a 5–8 expertos",
   "Identificar autores de los papers del corpus como expertos candidatos. Enviar Doc 02. Plazo sugerido: 15 días.",
   "MAYOR", C.naranja, "1 h envío\n+ 15 días espera", "Doc 02 ✓"],

  ["09", "Analizar respuestas de expertos y recalcular prioridades",
   "Con las respuestas del formulario, calcular media de impacto × frecuencia por gap. Actualizar Tabla 6 y Figura 5 con datos validados.",
   "MAYOR", C.naranja, "3–4 h", "Doc 02 ✓"],

  ["10", "Ampliar cadena de búsqueda",
   "Agregar términos faltantes: 'dung beetle optimizer', 'drone swarm agriculture', 'nutcracker optimization'. Añadir Scopus y Web of Science.",
   "MAYOR", C.naranja, "1 día", "Manual"],

  ["11", "Documentar snowballing correctamente",
   "Identificar los 5 seed papers usados en Research Rabbit. Especificar si fue forward/backward. Reportar cuántos de los 33 vienen de snowballing.",
   "MAYOR", C.naranja, "1 h", "Manual"],

  ["12", "Integrar Tabla de Características (Supplementary Table 1)",
   "Verificar y completar datos de S20–S33 con los PDFs reales. La tabla debe estar completa y sin datos estimados antes del envío.",
   "MAYOR", C.naranja, "3–4 h", "Doc 03 ✓"],

  ["13", "Justificar teóricamente el framework de 4 dimensiones",
   "Citar fuentes que respalden la clasificación Tecnológica/Práctica/Metodológica/Teórica. Agregar párrafo de justificación en Sección 3.3.",
   "MAYOR", C.naranja, "1 h", "Manuscrito"],

  ["14", "Agregar tabla comparativa de reviews previos en Related Work",
   "Desarrollar Sección 2 de media página con tabla: qué hace cada review previo y qué NO hace que sí hace este paper.",
   "MAYOR", C.naranja, "2 h", "Manuscrito"],

  ["15", "Eliminar o citar referencia a 'investigación doctoral en curso'",
   "Línea 183–185: compromete el anonimato en revisión doble-ciega. Eliminar o convertir en referencia citeable si ya existe publicación.",
   "MAYOR", C.naranja, "15 min", "Manuscrito"],

  // BLOQUE 3 — MENOR
  ["SEC3", "── BLOQUE 3: AJUSTES MENORES — Pulido final antes de enviar ──", "4472C4"],

  ["16", "Aplicar plantilla oficial Elsevier para CEA",
   "Descargar template Word/LaTeX de journals.elsevier.com/computers-and-electronics-in-agriculture. Reformatear todo el manuscrito.",
   "MENOR", "4472C4", "2–3 h", "Elsevier web"],

  ["17", "Agregar DOIs a todas las referencias",
   "Referencias [1]–[20] no tienen DOI. Buscar en doi.org o CrossRef para cada una y agregarlas en formato Elsevier.",
   "MENOR", "4472C4", "1 h", "CrossRef"],

  ["18", "Unificar etiquetas de figuras",
   "Las figuras tienen etiquetas A), B), C), D), E) que no coinciden con Figure 1–6 del texto. Renombrar consistentemente.",
   "MENOR", "4472C4", "30 min", "Manuscrito"],

  ["19", "Agregar 'Source: authors' systematic review, 2026' a cada figura",
   "CEA requiere fuente explícita y software usado en cada figura para reproducibilidad.",
   "MENOR", "4472C4", "30 min", "Manuscrito"],

  ["20", "Reformular cifras contradictorias en Sección 6.2",
   "'78.8% lack validation' y '21.2% have validation' son complementarias pero se leen como contradictorias. Usar formulación consistente.",
   "MENOR", "4472C4", "15 min", "Manuscrito"],

  ["21", "Matizar interpretación de datos 2025",
   "Los 6 papers de 2025 representan cobertura parcial (búsqueda el 16/03/2026). Agregar nota: 'data for 2025 may be incomplete'.",
   "MENOR", "4472C4", "15 min", "Manuscrito"],

  ["22", "Clarificar calidad de estudios Low (54.5%)",
