   "MENOR", "4472C4", "30 min", "Manuscrito"],

  ["24", "Verificar que Table 2 no mezcle reviews con algoritmos SI",
   "La categoría 'Review' en la distribución de algoritmos es metodológicamente incorrecta. Separar en análisis de subconjuntos.",
   "MENOR", "4472C4", "1 h", "Manuscrito"],

  ["25", "Depósito de datos suplementarios en Mendeley Data",
   "El Data Availability Statement promete depósito en Mendeley Data. Subir: Excel de gaps, scripts Python, BibTeX antes del envío.",
   "MENOR", "4472C4", "2 h", "Mendeley"],
];

// Build table rows
const tableRows = [];
// Header
tableRows.push(new TableRow({ children:[
  hdrCell("✓",420), hdrCell("#",380), hdrCell("Tarea y descripción",4000),
  hdrCell("Nivel",1100), hdrCell("Esfuerzo",900), hdrCell("Recurso disponible",1700)
]}));

for (const item of items) {
