}

// ─── PROGRESS TRACKER TABLE ───────────────────────────────────────────────────
const progressRow = (label, total, fill) => new TableRow({ children:[
  cell([new Paragraph({ children:[bold(label,18,C.gris)], spacing:{after:0} })], 2500, C.blanco),
  cell([new Paragraph({ alignment:AlignmentType.CENTER, children:[bold(`0 / ${total}`,18,fill)], spacing:{after:0} })], 1200, fill+"11"),
