        children:[new TextRun({ text:"Swarm Intelligence for Multi-UAV Path Planning in Precision Agriculture", size:24, italics:true, color:C.azulMed, font:"Arial" })],
        alignment:AlignmentType.CENTER, spacing:{ after:80 }
      }),
      new Paragraph({
        children:[new TextRun({ text:"Objetivo: Computers and Electronics in Agriculture  |  Elsevier  |  IF: 8.9  |  Q1", size:20, color:C.gris, font:"Arial" })],
