          new TableCell({ width:{size:2340,type:WidthType.DXA}, shading:{fill:C.narCla,type:ShadingType.CLEAR}, margins:{top:120,bottom:120,left:140,right:140}, borders:{top:{style:BorderStyle.SINGLE,size:2,color:C.naranja},bottom:{style:BorderStyle.SINGLE,size:2,color:C.naranja},left:{style:BorderStyle.SINGLE,size:2,color:C.naranja},right:{style:BorderStyle.SINGLE,size:2,color:C.naranja}},
