const p = (children, opts={}) => new Paragraph({ children: Array.isArray(children) ? children : [children], spacing:{after:100}, ...opts });
const pb = () => new Paragraph({ children:[new PageBreak()] });

const hdr1 = (text, color=C.azul) => new Paragraph({
  children:[new TextRun({ text, bold:true, size:32, color, font:"Arial" })],
