{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageBreak, LevelFormat, PageNumber, NumberFormat
} = require('docx');
const fs = require('fs');

const C = {
  azul:    "1F4E79", azulMed: "2E75B6", azulCla: "D6E4F0",
  gris:    "404040", grisCla: "F5F5F5", blanco:  "FFFFFF",
  verde:   "375623", verdeCla:"E2EFDA", verdeM:  "548235",
  rojo:    "C00000", rojoCla: "FCE4E4",
  amarillo:"806000", amarCla: "FFF2CC",
  naranja: "843C0C", narCla:  "FCE9D8",
};

const t  = (text, opts={}) => new TextRun({ text, font:"Arial", size:18, color:C.gris, ...opts });
const b  = (text, sz=18, color=C.gris) => new TextRun({ text, font:"Arial", size:sz, bold:true, color });
const it = (text, sz=18) => new TextRun({ text, font:"Arial", size:sz, italics:true, color:C.gris });
const p  = (children, opts={}) => new Paragraph({ children: Array.isArray(children)?children:[children], spacing:{after:80}, ...opts });
const pb = () => new Paragraph({ children:[new PageBreak()] });
const hdr1 = (text) => new Paragraph({
  children:[new TextRun({ text, bold:true, size:28, color:C.azul, font:"Arial" })],
  spacing:{ before:360, after:160 },
  border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color:C.azulMed, space:1 } }
});
const hdr2 = (text) => new Paragraph({
  children:[new TextRun({ text, bold:true, size:22, color:C.azulMed, font:"Arial" })],
  spacing:{ before:240, after:100 }
});

const bord = (color="CCCCCC", sz=1) => ({ style:BorderStyle.SINGLE, size:sz, color });
const borders = (color="CCCCCC") => ({ top:bord(color), bottom:bord(color), left:bord(color), right:bord(color) });

const hCell = (text, w, fill=C.azul) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill, type:ShadingType.CLEAR },
  margins:{ top:60, bottom:60, left:100, right:100 },
  borders: borders(fill),
  children:[new Paragraph({ alignment:AlignmentType.CENTER,
    children:[new TextRun({ text, bold:true, size:16, color:C.blanco, font:"Arial" })] })]
});

const dCell = (children, w, shade=C.blanco, align=AlignmentType.LEFT) => new TableCell({
  width:{ size:w, type:WidthType.DXA },
  shading:{ fill:shade, type:ShadingType.CLEAR },
  margins:{ top:60, bottom:60, left:100, right:100 },
  borders: borders(),
  children: Array.isArray(children) ? children :
    [new Paragraph({ alignment:align, children:[children], spacing:{after:0} })]
});

// MMAT scoring legend
// Q1: Is there an explicit research question? Yes/No/Can't tell
// Q2: Are collected data appropriate to address the question? Yes/No/Can't tell  
// Q3: Is the measurement valid and reliable? Yes/No/Can't tell
// Q4: Is the analysis appropriate? Yes/No/Can't tell
// Q5: Is there a coherent argument from data to conclusions? Yes/No/Can't tell
// Overall: High (4-5 Yes) / Moderate (2-3 Yes) / Low (0-1 Yes)

// Pre-filled data for all 33 studies based on available metadata
// Format: [ID, AuthorYear, Title_short, StudyType, Q1, Q2, Q3, Q4, Q5, Overall, Notes]
// Y=Yes, N=No, C=Can't tell, ?=Needs manual verification
const studies = [
  ["S01","Phung & Ha (2021)","PSO safety-enhanced UAV path planning","Quant. Simulation","Y","Y","Y","Y","Y","High","Full methodology; clear research question; PSO convergence validated"],
  ["S02","Pan et al. (2022)","Heterogeneous UAV border patrol SI","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Algorithm valid; measurement protocol unclear; no field validation"],
  ["S03","Ait Saadi et al. (2022)","UAV path planning optimization survey","Systematic Review","Y","Y","Y","Y","Y","High","PRISMA-aligned; comprehensive; clear inclusion criteria"],
  ["S04","Liu et al. (2021)","SSA + bioinspired neural network multi-UAV","Quant. Simulation","Y","Y","Y","Y","Y","High","Strong baseline comparison; convergence and time reported"],
  ["S05","Shafiq et al. (2022)","Max-min ACO multi-UAV convergence","Quant. Simulation","Y","Y","Y","Y","Y","High","Explicit convergence analysis; ACO parameters documented"],
  ["S06","Chen et al. (2021)","ACO coverage path planning heterogeneous UAV","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Coverage metric reported; measurement protocol partially unclear"],
