  ["S08","Liu et al. (2021)","GA+ABC disaster rescue multi-UAV","Quant. Simulation","Y","Y","C","Y","C","Moderate","Agricultural context weak; measurement validity unclear"],
  ["S09","Ntakolia & Lyridis (2021)","Fuzzy/SIGPAF swarm pathfinding","Quant. Simulation","Y","C","C","Y","Y","Moderate","Marine domain; agricultural application implied only"],
  ["S10","Xu et al. (2022)","Wolf Pack multi-discrete UAV task allocation","Quant. Simulation","Y","Y","C","Y","C","Moderate","Task allocation focus; measurement validity not addressed"],
  ["S11","Puente-Castro et al. (2022)","AI review UAV swarm path planning","Narrative Review","Y","Y","Y","Y","Y","High","Comprehensive review; clear taxonomy; good coverage"],
  ["S12","Li et al. (2023)","DBO obstacle avoidance swarm intelligence","Quant. Simulation","Y","Y","C","Y","Y","Moderate","DBO novel; energy reported; measurement protocol unclear"],
  ["S13","Fevgas et al. (2022)","Coverage path planning energy cooperative UAV","Literature Review","Y","Y","Y","Y","Y","High","Energy-focused review; cooperative strategies well covered"],
  ["S14","Selma et al. (2022)","ABC ANFIS controller trajectory quadrotor","Quant. Sim+Testbed","Y","Y","Y","Y","Y","High","Hardware validated; trajectory tracking metrics clear"],
  ["S15","Ji et al. (2022)","PSO biogeography-based double-dynamic","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Novel PSO variant; convergence reported; validation limited"],
  ["S16","Xiao et al. (2025)","NOA multi-UAV path planning improved","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Recent algorithm; measurement protocol requires verification"],
  ["S17","Chu et al. (2022)","Chaos PSO UAV safe path planning","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Chaos operator novel; no energy measurement; time reported"],
  ["S18","Sharma et al. (2022)","SI algorithms multi-UAV interception review","Systematic Review","Y","Y","Y","Y","Y","High","Good performance comparison table; clear inclusion criteria"],
  ["S19","Israr et al. (2022)","Optimization methods UAV motion planning review","Literature Review","Y","Y","Y","Y","Y","High","Broad coverage; SI vs non-SI comparison clear"],
  ["S20","Ahmed et al. (2021)","3D path planning multi-UAV surveillance PSO","Quant. Simulation","Y","Y","C","Y","Y","Moderate","3D environment; measurement validity partially unclear"],
  ["S21","Yu et al. (2021)","Sparrow particle swarm SPSA UAV","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Hybrid PSO-SSA; convergence reported; no energy"],
  ["S22","Mathew et al. (2021)","Swarm intelligence path planning implementation","Quant. Simulation","Y","C","C","C","C","Low","Short conference paper; limited methodological detail"],
  ["S23","Li et al. (2025)","Enhanced ACO global path planning robots","Quant. Simulation","Y","Y","Y","Y","Y","High","Strong ACO enhancement; full metric suite reported"],
  ["S24","Wang et al. (2025)","Hybrid SI mobile platform multi-dimensional","Quant. Sim+Testbed","Y","Y","Y","Y","Y","High","Hardware testbed; multiple SI algorithms compared"],
  ["S25","Hu et al. (2025)","PSO fuzzy controller multi-robot path","Quant. Simulation","Y","Y","C","Y","Y","Moderate","Fuzzy integration novel; measurement partially unclear"],
  ["S26","Deng et al. (2023)","3D UAV path planning improved PSO","Quant. Simulation","Y","Y","C","Y","Y","Moderate","3D PSO variant; limited metric reporting"],
  ["S27","Rao et al. (2024)","Multi-strategy collaborative GWO UAV","Quant. Simulation","Y","Y","Y","Y","Y","High","GWO multi-strategy; convergence and time reported; baseline comparison"],
  ["S28","Zhang & Zhang (2022)","UAV localization PSO efficient","Quant. Simulation","Y","C","C","Y","C","Low","Localization focus; agricultural application weak; limited detail"],
  ["S29","Liu et al. (2021)","Modified SSA 3D route planning UAV","Quant. Simulation","Y","Y","Y","Y","Y","High","SSA modification clear; 3D environment; convergence reported"],
  ["S30","Tang et al. (2022)","SI algorithms multi-UAV collaboration review","Systematic Review","Y","Y","Y","Y","Y","High","Comprehensive review; good algorithm taxonomy"],
  ["S31","Yang et al. (2023)","UAV formation trajectory planning review","Literature Review","Y","Y","Y","Y","Y","High","Formation planning focus; good coverage of SI methods"],
  ["S32","Yang et al. (2025)","3D UAV path planning dream optimization DOA","Quant. Simulation","?","?","?","?","?","?","Metadata inferred — requires manual PDF verification"],
  ["S33","Zuo et al. (2025)","Hybrid APF-PSO UAV swarm formation","Quant. Simulation","?","?","?","?","?","?","Metadata inferred — requires manual PDF verification"],
];

const W = 14200; // landscape content width
// Col widths: ID, Author, Title, Type, Q1, Q2, Q3, Q4, Q5, Overall, Notes
const cw = [420, 1500, 2800, 1400, 560, 560, 560, 560, 560, 900, 3380];

const scoreColor = (s) => {
  if (s === 'High')     return C.verdeCla;
  if (s === 'Moderate') return C.amarCla;
  if (s === 'Low')      return C.rojoCla;
  return C.grisCla;
};
const scoreTextColor = (s) => {
  if (s === 'High')     return C.verdeM;
  if (s === 'Moderate') return C.amarillo;
  if (s === 'Low')      return C.rojo;
  return C.gris;
};
const qColor = (v) => {
  if (v === 'Y') return C.verdeCla;
  if (v === 'N') return C.rojoCla;
  if (v === 'C') return C.amarCla;
  return C.grisCla;
};

function studyRow(study, shade) {
  const [id, auth, title, type, q1, q2, q3, q4, q5, overall, notes] = study;
  const qs = [q1,q2,q3,q4,q5];
  return new TableRow({ children:[
