        spacing:{after:0}})] })),
    // Overall
    new TableCell({ width:{size:cw[9],type:WidthType.DXA},
      shading:{fill:scoreColor(overall),type:ShadingType.CLEAR},
      margins:{top:50,bottom:50,left:80,right:80}, borders:borders(),
      children:[new Paragraph({alignment:AlignmentType.CENTER,
        children:[b(overall,15,scoreTextColor(overall))], spacing:{after:0}})] }),
