    new TableCell({ width:{size:cw[10],type:WidthType.DXA}, shading:{fill:shade,type:ShadingType.CLEAR},
      margins:{top:50,bottom:50,left:80,right:80}, borders:borders(),
      children:[new Paragraph({ children:[t(notes,{size:14,color:"555555"})], spacing:{after:0}})] }),
  ]});
}

// Summary counts
const counts = { High:0, Moderate:0, Low:0, Pending:0 };
studies.forEach(s => {
  if (s[9]==='High') counts.High++;
  else if (s[9]==='Moderate') counts.Moderate++;
  else if (s[9]==='Low') counts.Low++;
  else counts.Pending++;
});

const doc = new Document({
  styles:{ default:{ document:{ run:{ font:"Arial", size:18, color:C.gris } } } },
