      }),
      new Paragraph({
        children:[t("Swarm Intelligence for Multi-UAV Path Planning in Precision Agriculture (2021–2025)  |  n = 33 estudios",20)],
        alignment:AlignmentType.CENTER, spacing:{after:60}
      }),
      new Paragraph({
        children:[t("Instrumento: MMAT 2018 (Hong et al.) adaptado para estudios de ingeniería computacional  |  Revisor 1: Andres Hidalgo Morales  |  Revisor 2: [Director de tesis]",16,C.gris)],
        alignment:AlignmentType.CENTER, spacing:{after:200}
      }),

      // LEGEND
      new Table({
        width:{size:W,type:WidthType.DXA}, columnWidths:[W/5,W/5,W/5,W/5,W/5],
        rows:[
          new TableRow({ children:[
            new TableCell({ width:{size:W/5,type:WidthType.DXA}, shading:{fill:C.azul,type:ShadingType.CLEAR},
              margins:{top:80,bottom:80,left:120,right:120}, borders:borders(C.azul),
              children:[new Paragraph({alignment:AlignmentType.CENTER, children:[b("CRITERIOS MMAT",17,C.blanco)], spacing:{after:0}})] }),
            new TableCell({ width:{size:W/5,type:WidthType.DXA}, shading:{fill:C.verdeCla,type:ShadingType.CLEAR},
              margins:{top:80,bottom:80,left:120,right:120}, borders:borders(),
              children:[new Paragraph({alignment:AlignmentType.CENTER, children:[b("Y = Sí",17,C.verdeM)], spacing:{after:40}}),
                new Paragraph({alignment:AlignmentType.CENTER, children:[t("Criterio cumplido",15,C.gris)], spacing:{after:0}})] }),
            new TableCell({ width:{size:W/5,type:WidthType.DXA}, shading:{fill:C.amarCla,type:ShadingType.CLEAR},
              margins:{top:80,bottom:80,left:120,right:120}, borders:borders(),
              children:[new Paragraph({alignment:AlignmentType.CENTER, children:[b("C = Can't tell",17,C.amarillo)], spacing:{after:40}}),
                new Paragraph({alignment:AlignmentType.CENTER, children:[t("No determinable",15,C.gris)], spacing:{after:0}})] }),
            new TableCell({ width:{size:W/5,type:WidthType.DXA}, shading:{fill:C.rojoCla,type:ShadingType.CLEAR},
              margins:{top:80,bottom:80,left:120,right:120}, borders:borders(),
              children:[new Paragraph({alignment:AlignmentType.CENTER, children:[b("N = No",17,C.rojo)], spacing:{after:40}}),
                new Paragraph({alignment:AlignmentType.CENTER, children:[t("Criterio no cumplido",15,C.gris)], spacing:{after:0}})] }),
            new TableCell({ width:{size:W/5,type:WidthType.DXA}, shading:{fill:C.grisCla,type:ShadingType.CLEAR},
              margins:{top:80,bottom:80,left:120,right:120}, borders:borders(),
              children:[new Paragraph({alignment:AlignmentType.CENTER, children:[b("? = Verificar",17,C.gris)], spacing:{after:40}}),
                new Paragraph({alignment:AlignmentType.CENTER, children:[t("Requiere PDF manual",15,C.gris)], spacing:{after:0}})] }),
          ]})
        ]
      }),
      p([]),

      // CRITERIA EXPLANATION
      new Table({
        width:{size:W,type:WidthType.DXA}, columnWidths:[560,560,560,560,560,W-2800],
        rows:[
          new TableRow({ children:[
            hCell("Q1",560,C.azulMed), hCell("Q2",560,C.azulMed), hCell("Q3",560,C.azulMed),
            hCell("Q4",560,C.azulMed), hCell("Q5",560,C.azulMed),
            hCell("Descripción de criterios MMAT adaptados para SI-UAV",W-2800,C.azulMed),
          ]}),
          new TableRow({ children:[
            dCell([new Paragraph({children:[b("Q1",16,C.azulMed)],spacing:{after:20}}),
                   new Paragraph({children:[t("Pregunta\nde invest.",14)],spacing:{after:0}})], 560, C.azulCla),
            dCell([new Paragraph({children:[b("Q2",16,C.azulMed)],spacing:{after:20}}),
                   new Paragraph({children:[t("Datos\napropiados",14)],spacing:{after:0}})], 560, C.azulCla),
            dCell([new Paragraph({children:[b("Q3",16,C.azulMed)],spacing:{after:20}}),
                   new Paragraph({children:[t("Medición\nválida",14)],spacing:{after:0}})], 560, C.azulCla),
            dCell([new Paragraph({children:[b("Q4",16,C.azulMed)],spacing:{after:20}}),
                   new Paragraph({children:[t("Análisis\napropiado",14)],spacing:{after:0}})], 560, C.azulCla),
            dCell([new Paragraph({children:[b("Q5",16,C.azulMed)],spacing:{after:20}}),
                   new Paragraph({children:[t("Argumento\ncoherente",14)],spacing:{after:0}})], 560, C.azulCla),
            new TableCell({ width:{size:W-2800,type:WidthType.DXA}, shading:{fill:C.grisCla,type:ShadingType.CLEAR},
              margins:{top:60,bottom:60,left:120,right:120}, borders:borders(),
