const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageBreak, LevelFormat
} = require('docx');
const fs = require('fs');

const C = {
  azul:"1F4E79", azulMed:"2E75B6", azulCla:"D6E4F0",
  gris:"404040", grisCla:"F5F5F5", blanco:"FFFFFF",
  verde:"375623", verdeCla:"E2EFDA", verdeM:"548235",
  amarCla:"FFF2CC", amarillo:"806000",
};

const t  = (text, opts={}) => new TextRun({ text, font:"Arial", size:20, color:C.gris, ...opts });
const b  = (text, sz=20, color=C.gris) => new TextRun({ text, font:"Arial", size:sz, bold:true, color });
const p  = (children, opts={}) => new Paragraph({ children:Array.isArray(children)?children:[children], spacing:{after:120}, ...opts });
const pb = () => new Paragraph({ children:[new PageBreak()] });
const hdr1 = (text) => new Paragraph({
  children:[new TextRun({text, bold:true, size:28, color:C.azul, font:"Arial"})],
  spacing:{before:360,after:160},
  border:{bottom:{style:BorderStyle.SINGLE,size:6,color:C.azulMed,space:1}}
});
const hdr2 = (text, color=C.azulMed) => new Paragraph({
  children:[new TextRun({text, bold:true, size:22, color, font:"Arial"})],
  spacing:{before:240,after:100}
});
const bord = (c="CCCCCC") => ({top:{style:BorderStyle.SINGLE,size:1,color:c},bottom:{style:BorderStyle.SINGLE,size:1,color:c},left:{style:BorderStyle.SINGLE,size:1,color:c},right:{style:BorderStyle.SINGLE,size:1,color:c}});
const hCell = (text,w,fill=C.azul) => new TableCell({width:{size:w,type:WidthType.DXA},shading:{fill,type:ShadingType.CLEAR},margins:{top:70,bottom:70,left:100,right:100},borders:bord(fill),children:[new Paragraph({alignment:AlignmentType.CENTER,children:[b(text,17,C.blanco)],spacing:{after:0}})]});
const dCell = (text,w,shade=C.blanco,sz=18,color=C.gris) => new TableCell({width:{size:w,type:WidthType.DXA},shading:{fill:shade,type:ShadingType.CLEAR},margins:{top:70,bottom:70,left:100,right:100},borders:bord(),children:[new Paragraph({children:[new TextRun({text,font:"Arial",size:sz,color})],spacing:{after:0}})]});
const W = 9360;

const experts = [
  {
    n: 1, key: "phung2021", name: "Dr. Manh Duong Phung",
    inst: "University of Technology Sydney, Australia",
    paper: "Safety-enhanced UAV path planning with spherical vector-based PSO",
    journal: "Applied Soft Computing (IF: 8.7), 2021",
    doi: "10.1016/j.asoc.2021.107376",
    expertise: "PSO-based UAV path planning, agricultural safety constraints",
    email_hint: "Search: 'Manh Duong Phung UTS email' or ResearchGate profile",
    personalisation: "your spherical vector PSO approach directly addresses the kinematic constraint gaps (G06) identified in our analysis, making your perspective on deployment barriers particularly valuable"
  },
  {
    n: 2, key: "shafiq2022", name: "Dr. Muhammad Shafiq",
    inst: "King Abdulaziz University, Saudi Arabia",
    paper: "Convergence analysis of multi-UAVs using max-min ACO",
    journal: "Sensors (MDPI), 2022",
    doi: "10.3390/s22145395",
    expertise: "ACO multi-UAV coordination, convergence analysis",
    email_hint: "Search: 'Muhammad Shafiq KAU email' or IEEE profile",
    personalisation: "your convergence analysis work directly addresses one of the most critical methodological gaps (G05, G15) identified in our corpus — the absence of standardised convergence criteria"
  },
  {
    n: 3, key: "puente2022", name: "Dr. Alejandro Puente-Castro",
    inst: "University of A Coruña, Spain",
    paper: "A review of artificial intelligence applied to path planning in UAV swarms",
    journal: "Neural Computing and Applications (IF: 6.0), 2022",
    doi: "10.1007/s00521-021-06569-4",
    expertise: "Systematic review SI-UAV, algorithm taxonomy",
    email_hint: "Search: 'Alejandro Puente Castro UDC email' or Google Scholar",
    personalisation: "as the author of the closest antecedent review to our work, your perspective on what gaps have been addressed since 2021 and which remain open would be especially insightful for the gap prioritisation process"
  },
  {
    n: 4, key: "sharma2022", name: "Dr. Abhishek Sharma",
    inst: "Thapar Institute of Engineering and Technology, India",
    paper: "Path planning for multiple targets interception by UAV swarms: A review",
    journal: "IETE Technical Review, 2022",
    doi: "10.1080/02564602.2021.1894250",
    expertise: "Multi-UAV swarm coordination, SI algorithm comparison",
    email_hint: "Search: 'Abhishek Sharma Thapar email' or ResearchGate",
    personalisation: "your comparative performance table across PSO, ACO, ABC, and GWO algorithms directly inspired our quantitative synthesis approach, and your view on metric standardisation gaps would be particularly relevant"
  },
  {
    n: 5, key: "aitsaadi2022", name: "Dr. Amylia Ait Saadi",
    inst: "USTHB, Algeria",
    paper: "UAV path planning using optimization approaches: A survey",
    journal: "Archives of Computational Methods in Engineering, 2022",
    doi: "10.1007/s11831-022-09742-7",
    expertise: "Broad UAV optimisation survey, SI and non-SI methods",
    email_hint: "Search: 'Amylia Ait Saadi USTHB email' or ResearchGate",
    personalisation: "your comprehensive survey of 153 papers provides the broadest view of the optimisation landscape, and your assessment of which gaps remain most critical after narrowing to the 2021-2025 agricultural SI-specific domain would be particularly informative"
  },
  {
    n: 6, key: "chen2021", name: "Dr. Jinchao Chen",
    inst: "National University of Defense Technology, China",
    paper: "Coverage path planning of heterogeneous UAVs based on ant colony system",
    journal: "Swarm and Evolutionary Computation (IF: 10.3), 2021",
    doi: "10.1016/j.swevo.2021.101005",
    expertise: "ACO heterogeneous UAV coverage, agricultural field planning",
    email_hint: "Search: 'Jinchao Chen NUDT email' or IEEE Xplore author page",
    personalisation: "your heterogeneous UAV coverage work addresses both the scalability gap (G07) and the homogeneous fleet limitation (G14) that our analysis identifies as critical barriers — your practical experience with these challenges is precisely what this validation needs"
  },
  {
    n: 7, key: "tang2022", name: "Dr. Jun Tang",
    inst: "Beihang University (BUAA), China",
    paper: "Swarm intelligence algorithms for multiple UAVs collaboration: A comprehensive review",
    journal: "Artificial Intelligence Review (IF: 12.0), 2022",
    doi: "10.1007/s10462-022-10281-7",
    expertise: "SI multi-UAV collaboration, comprehensive algorithm review",
    email_hint: "Search: 'Jun Tang Beihang UAV email' or Google Scholar",
    personalisation: "your comprehensive review in Artificial Intelligence Review covers the broadest algorithm scope in our corpus, and your perspective on which collaboration gaps are most critical for field deployment versus theoretical development would be highly valuable"
  },
  {
    n: 8, key: "fevgas2022", name: "Dr. Georgios Fevgas",
    inst: "University of Western Macedonia, Greece",
    paper: "Coverage path planning focusing on energy efficient and cooperative UAV strategies",
    journal: "Sensors (MDPI), 2022",
    doi: "10.3390/s22031235",
    expertise: "Energy-efficient UAV coverage, cooperative strategies",
    email_hint: "Search: 'Georgios Fevgas UWM email' or ResearchGate",
    personalisation: "your energy-focused coverage work directly addresses two of our top-10 critical gaps: absent direct energy measurement (G08) and limited scalability assessment (G07) — your practical insights on energy modelling barriers would strengthen the deployment-impact validation"
  },
];

const emailBody = (exp) => `Dear ${exp.name.replace('Dr. ','').replace('Prof. ','')},

I am Andres Hidalgo Morales, a researcher at Instituto Tecnológico de Chihuahua II (Tecnológico Nacional de México). I am finalising a systematic review titled "Swarm Intelligence for Multi-UAV Path Planning in Precision Agriculture: A Systematic Review and Research Agenda (2021–2025)," targeting Computers and Electronics in Agriculture (Elsevier, IF: 8.9).

Your paper "${exp.paper}" (${exp.journal}) is one of the 33 studies included in our corpus. Specifically, ${exp.personalisation}.

I would like to invite you to participate as an expert validator for our research gap prioritisation analysis. The task involves rating 15 identified gaps on two dimensions — deployment impact and literature frequency — using a short Likert-scale questionnaire (25–30 minutes). Your participation will be formally acknowledged in the manuscript.

If you are willing to participate, I will send you the questionnaire (attached as a Word document) immediately. The response deadline is 15 days from receipt.

Thank you for considering this request.

Best regards,
Andres Hidalgo Morales
Instituto Tecnológico de Chihuahua II, TecNM
hidalmora79@gmail.com
DOI of your included paper: ${exp.doi}`;

const children = [
  // COVER PAGE
  new Paragraph({children:[b("PAQUETE DE OUTREACH A EXPERTOS",28,C.azul)],alignment:AlignmentType.CENTER,spacing:{before:600,after:160}}),
  new Paragraph({children:[t("Validación de gaps — Systematic Review CEA",22)],alignment:AlignmentType.CENTER,spacing:{after:80}}),
  new Paragraph({children:[t("8 expertos seleccionados | Correos personalizados listos | Plazo: 15 días",18,C.gris)],alignment:AlignmentType.CENTER,spacing:{after:480}}),

  // Summary table
  hdr1("Resumen de los 8 expertos seleccionados"),
  p([t("Criterios de selección: (1) autores del corpus 2021–2025, (2) diversidad de algoritmos cubiertos, (3) publicación en revista IF>4, (4) dominio multi-UAV o SI agrícola, (5) diversidad geográfica.",18,C.gris)]),
  p([]),
  new Table({
    width:{size:W,type:WidthType.DXA}, columnWidths:[380,2000,1800,1900,1800,1480],
    rows:[
      new TableRow({children:[hCell("#",380),hCell("Nombre",2000),hCell("Institución",1800),hCell("Paper clave",1900),hCell("Experticia",1800),hCell("Email (buscar)",1480)]}),
      ...experts.map((e,i) => new TableRow({children:[
        dCell(`${e.n}`,380,i%2?C.blanco:C.grisCla,18,C.azulMed),
        dCell(e.name,2000,i%2?C.blanco:C.grisCla,17),
        dCell(e.inst,1800,i%2?C.blanco:C.grisCla,15,"666666"),
        dCell(e.journal,1900,i%2?C.blanco:C.grisCla,15,"666666"),
        dCell(e.expertise,1800,i%2?C.blanco:C.grisCla,15),
        dCell(e.email_hint,1480,i%2?C.blanco:C.grisCla,14,"666666"),
      ]}))
    ]
  }),
  p([]),

  // Tracking table
  hdr2("Tracker de respuestas (actualizar conforme lleguen)"),
  new Table({
    width:{size:W,type:WidthType.DXA}, columnWidths:[380,2000,1200,1200,1200,1200,2180],
    rows:[
      new TableRow({children:[hCell("#",380),hCell("Experto",2000),hCell("Email enviado",1200),hCell("Fecha envío",1200),hCell("Respuesta",1200),hCell("Formulario recibido",1200),hCell("Notas",2180)]}),
      ...experts.map((e,i) => new TableRow({children:[
        dCell(`${e.n}`,380,i%2?C.blanco:C.grisCla,18,C.azulMed),
        dCell(e.name.replace('Dr. ',''),2000,i%2?C.blanco:C.grisCla,16),
        dCell("☐",1200,i%2?C.blanco:C.grisCla,18),
        dCell("___/___/2026",1200,i%2?C.blanco:C.grisCla,16),
        dCell("☐ Sí  ☐ No  ☐ P.",1200,i%2?C.blanco:C.grisCla,15),
        dCell("☐",1200,i%2?C.blanco:C.grisCla,18),
        dCell("",2180,i%2?C.blanco:C.grisCla,15),
      ]}))
    ]
  }),
  p([t("Meta: ≥5 respuestas válidas para cálculo estadístico. Con 5 respuestas ya puedes calcular la media de impacto×frecuencia y actualizar la clasificación de gaps.",16,C.gris)]),
  p([]),
  pb(),

  // Individual emails
  hdr1("Correos personalizados — listos para enviar"),
  p([t("Personaliza el email según el experto. El asunto es idéntico para todos. Adjunta el Doc 02 (Formulario de Validación de Gaps) en cada correo.",16,C.gris)]),
  p([b("Asunto (igual para todos): ",18), t("Expert Validation Request: Gap Analysis in SI-based Multi-UAV Path Planning for Precision Agriculture",18)]),
  p([]),

  ...experts.flatMap((e,i) => [
    new Paragraph({
      children:[b(`Experto ${e.n} — ${e.name}`, 22, C.azulMed)],
      spacing:{before:280,after:80},
      border:{left:{style:BorderStyle.SINGLE,size:8,color:C.azulMed,space:8}}
    }),
    p([b("Institución: ",18), t(e.inst,18)]),
    p([b("Buscar email en: ",18), t(e.email_hint,18,C.azulMed)]),
    p([b("DOI paper incluido: ",18), t(e.doi,18)]),
    p([]),
    new Table({
      width:{size:W,type:WidthType.DXA}, columnWidths:[W],
      rows:[new TableRow({children:[new TableCell({
        width:{size:W,type:WidthType.DXA},
        shading:{fill:C.grisCla,type:ShadingType.CLEAR},
        margins:{top:140,bottom:140,left:180,right:180},
        borders:{top:{style:BorderStyle.SINGLE,size:2,color:C.azulMed},bottom:{style:BorderStyle.SINGLE,size:2,color:C.azulMed},left:{style:BorderStyle.SINGLE,size:2,color:C.azulMed},right:{style:BorderStyle.SINGLE,size:2,color:C.azulMed}},
        children: emailBody(e).split('\n').map(line =>
          new Paragraph({children:[t(line,17)], spacing:{after:line===''?80:40}})
        )
      })})]
    }),
    i < experts.length-1 ? p([]) : p([]),
    i < experts.length-1 ? pb() : p([]),
  ]),

  // Follow-up strategy
  pb(),
  hdr1("Estrategia de seguimiento"),
  new Table({
    width:{size:W,type:WidthType.DXA}, columnWidths:[1400,5200,2760],
    rows:[
      new TableRow({children:[hCell("Día",1400),hCell("Acción",5200),hCell("Texto sugerido",2760)]}),
      new TableRow({children:[dCell("Día 0",1400,C.verdeCla,18,C.verdeM),dCell("Enviar invitación inicial con Doc 02 adjunto",5200,C.verdeCla),dCell("Email personalizado arriba",2760,C.verdeCla)]}),
      new TableRow({children:[dCell("Día 8",1400,C.amarCla,18,C.amarillo),dCell("Reminder si no hay respuesta: 1 sola vez, breve",5200,C.amarCla),dCell('"Just a gentle reminder..."',2760,C.amarCla)]}),
      new TableRow({children:[dCell("Día 15",1400,C.grisCla),dCell("Cierre: agradecer a quienes respondieron, registrar no-respuestas",5200,C.grisCla),dCell("Calcular kappa con respuestas disponibles",2760,C.grisCla)]}),
      new TableRow({children:[dCell("Post análisis",1400,C.azulCla,18,C.azulMed),dCell("Enviar resumen de resultados a todos los participantes (cortesía académica)",5200,C.azulCla),dCell("Aumenta probabilidad de futura colaboración",2760,C.azulCla)]}),
    ]
  }),
  p([]),
  new Paragraph({
    children:[b("Criterio de suficiencia: ",18,C.azulMed), t("Con ≥5 respuestas puedes calcular estadísticas válidas (media, desviación, α de Cronbach para consistencia interna). Si obtienes <5 en 15 días, envía a 3 expertos adicionales del corpus (candidatos: Selma, Xiao, Rao).",18)],
    spacing:{before:120,after:0},
    border:{left:{style:BorderStyle.SINGLE,size:6,color:C.azulMed,space:8}}
  }),
];

const doc = new Document({
  styles:{default:{document:{run:{font:"Arial",size:20,color:C.gris}}}},
  sections:[{
    properties:{page:{size:{width:12240,height:15840},margin:{top:1080,right:1080,bottom:1080,left:1080}}},
    children
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/Expertos_Gaps_Outreach.docx', buf);
  console.log('✓ Expertos_Gaps_Outreach.docx generado');
  console.log('  8 correos personalizados + tracker + estrategia seguimiento');
});

