const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType, PageBreak
} = require('docx');
const fs = require('fs');

const C = {
  azul:"1F4E79", azulMed:"2E75B6", azulCla:"D6E4F0",
  gris:"404040", grisCla:"F5F5F5", blanco:"FFFFFF",
  verde:"375623", verdeCla:"E2EFDA",
  amarCla:"FFF2CC", amarillo:"806000",
};

const t  = (text, opts={}) => new TextRun({ text, font:"Arial", size:20, color:C.gris, ...opts });
const b  = (text, sz=20, color=C.gris) => new TextRun({ text, font:"Arial", size:sz, bold:true, color });
const it = (text, sz=20) => new TextRun({ text, font:"Arial", size:sz, italics:true, color:C.gris });
const p  = (children, opts={}) => new Paragraph({ children:Array.isArray(children)?children:[children], spacing:{after:120}, ...opts });
const pb = () => new Paragraph({ children:[new PageBreak()] });

const bord = (c="CCCCCC",sz=1) => ({top:{style:BorderStyle.SINGLE,size:sz,color:c},bottom:{style:BorderStyle.SINGLE,size:sz,color:c},left:{style:BorderStyle.SINGLE,size:sz,color:c},right:{style:BorderStyle.SINGLE,size:sz,color:c}});

const hCell = (text, w, fill=C.azul, sz=17) => new TableCell({
  width:{size:w,type:WidthType.DXA},
  shading:{fill,type:ShadingType.CLEAR},
  margins:{top:80,bottom:80,left:120,right:120},
  borders:bord(fill,2),
  children:[new Paragraph({alignment:AlignmentType.LEFT,
    children:[new TextRun({text,bold:true,size:sz,color:C.blanco,font:"Arial"})],
    spacing:{after:0}})]
});

const dCell = (text, w, shade=C.blanco, sz=18, color=C.gris, align=AlignmentType.LEFT) => new TableCell({
  width:{size:w,type:WidthType.DXA},
  shading:{fill:shade,type:ShadingType.CLEAR},
  margins:{top:80,bottom:80,left:120,right:120},
  borders:bord(),
  children:[new Paragraph({alignment:align,
    children:[new TextRun({text,font:"Arial",size:sz,color})],
    spacing:{after:0}})]
});

const dCellMulti = (paras, w, shade=C.blanco) => new TableCell({
  width:{size:w,type:WidthType.DXA},
  shading:{fill:shade,type:ShadingType.CLEAR},
  margins:{top:80,bottom:80,left:120,right:120},
  borders:bord(),
  children:paras
});

const W = 9360;

const gaps = [
  ["G01","Lack of hardware/field validation","Practical","78.8%"],
  ["G02","No dynamic obstacles/environment modeling","Practical","75.8%"],
  ["G03","Single-UAV focus (no swarm coordination)","Methodological","66.7%"],
  ["G04","No wind/weather modeling","Technological","60.6%"],
  ["G05","No metric standardization across studies","Methodological","54.5%"],
  ["G06","Unrealistic kinematic constraints","Technological","45.5%"],
  ["G07","Limited scalability assessment (>5 UAVs)","Technological","42.4%"],
  ["G08","No direct energy measurement (estimated only)","Practical","39.4%"],
  ["G09","Communication robustness ignored","Technological","36.4%"],
  ["G10","No real-time replanning capability","Practical","33.3%"],
  ["G11","Lack of multi-crop/terrain diversity in evaluation","Practical","30.3%"],
  ["G12","No fault tolerance mechanisms","Technological","27.3%"],
  ["G13","Absence of regulatory compliance modeling","Practical","27.3%"],
  ["G14","No heterogeneous UAV fleet support","Technological","24.2%"],
  ["G15","Missing convergence criteria reporting","Methodological","21.2%"],
];

