  dCell("☐ 1   ☐ 2   ☐ 3   ☐ 4   ☐ 5", 1300, shade, 17, C.gris, AlignmentType.CENTER),
  dCell("", 1000, shade),
]});

const children = [

  // ── HEADER ──────────────────────────────────────────────────────────────────
  new Paragraph({
    children:[b("EXPERT VALIDATION QUESTIONNAIRE", 32, C.azul)],
    alignment:AlignmentType.CENTER, spacing:{before:480,after:160}
