        new Paragraph({children:[b("Estimated time: ",18,C.gris), t("25–30 minutes  |  ", 18), b("Deadline: ",18,C.gris), t("15 days from receipt  |  ", 18), b("Return to: ",18,C.gris), t("hidalmora79@gmail.com",18)]}, spacing:{after:0}),
      ]
    })})]
  }),
