  p([]),
  new Table({
    width:{size:W,type:WidthType.DXA}, columnWidths:[3200,6160],
    rows:[
      new TableRow({children:[hCell("Field",3200,C.azul,17), hCell("Your response",6160,C.azul,17)]}),
