      new TableRow({children:[dCell("Country",3200,C.grisCla), dCell("",6160,C.grisCla)]}),
      new TableRow({children:[dCell("Years of experience in UAVs / agricultural robotics",3200), dCell("☐ 1–3 years   ☐ 4–7 years   ☐ 8–12 years   ☐ >12 years",6160)]}),
      new TableRow({children:[dCell("Primary area of expertise",3200,C.grisCla), dCell("☐ SI/metaheuristic algorithms   ☐ Multi-UAV systems   ☐ Precision agriculture   ☐ Field robotics   ☐ Other: _______",6160,C.grisCla)]}),
      new TableRow({children:[dCell("Number of publications in SI or multi-UAV systems",3200), dCell("☐ 1–5   ☐ 6–15   ☐ 16–30   ☐ >30",6160)]}),
      new TableRow({children:[dCell("ORCID (optional)",3200,C.grisCla), dCell("",6160,C.grisCla)]}),
    ]
  }),
  p([]), p([]),
  pb(),

  // ── SECTION B — INSTRUCTIONS ─────────────────────────────────────────────────
