        new Paragraph({children:[b("Column 1 — DEPLOYMENT IMPACT: ",18,C.azulMed), t("How critical is this gap in preventing the real-world field deployment of multi-UAV systems in precision agriculture? (1 = negligible barrier; 5 = critical blocker for deployment)",18)], spacing:{after:80}}),
        new Paragraph({children:[b("Column 2 — LITERATURE FREQUENCY: ",18,C.azulMed), t("How frequently do you observe this gap in the recent literature of your area? (1 = rarely present; 5 = ubiquitous across studies)",18)], spacing:{after:100}}),
